import { NgFor, NgIf } from '@angular/common';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  inject,
  Input,
  OnChanges,
  OnInit,
  Output,
  Renderer2,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { QSharedResizeObserverService } from '@questrade/allspark-angular-components/core/services';
import { injectDestroy } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';
import { carouselAnimation } from './carousel.animation';
import { QCarouselSize } from './types/carousel-size.type';
import { QCarouselVariant } from './types/carousel-variant.type';

const MAX_INDICATORS = 10;

@Component({
  imports: [NgIf, NgFor],
  selector: 'q-carousel',
  templateUrl: './carousel.component.html',
  styleUrls: ['./carousel.component.scss'],
  animations: [carouselAnimation],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QCarouselComponent implements OnInit, AfterViewInit, OnChanges {
  @Output() readonly changed = new EventEmitter<number>();

  @Input({ transform: booleanAttribute }) centered = true;
  @Input({ transform: booleanAttribute }) absolute = false;
  @Input() type: QCarouselVariant = 'tight';
  @Input() size: QCarouselSize = 'medium';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-carousel';

  @Input() set marginTop(value: number) {
    this._renderer.setStyle(this._elementRef.nativeElement, 'margin-top', `${value}px`);
  }

  @Input() set marginBottom(value: number) {
    this._renderer.setStyle(this._elementRef.nativeElement, 'margin-bottom', `${value}px`);
  }

  @Input() set items(value: number) {
    this._indicatorsCount = value > MAX_INDICATORS ? MAX_INDICATORS : value;

    if (this._activeItem > this._indicatorsCount) {
      this._updateActiveIndicator(value);
    }
  }

  @Input() set active(value: number) {
    if (value > this._indicatorsCount || value < 1) return;

    this._oldActiveItem = this._activeItem;
    this._activeItem = value;

    if (this._oldActiveItem > 0) {
      this._animate();
    }
  }

  @ViewChild('activeItem') activeItemRef!: ElementRef<HTMLElement>;

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-carousel',
      `q-carousel-${this.type}`,
      `q-carousel-${this.size}`,
      this.centered && 'q-carousel-centered',
      this.absolute && 'q-carousel-absolute',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _activeItemIndicatorXPosition = 0;
  _activeItem = 0;
  _animateRight = false;
  _animateLeft = false;
  _indicatorsCount = 0;

  private _oldActiveItem!: number;
  private _activeOffset = 0;
  private readonly _destroy$ = injectDestroy();
  private readonly _resizeObserver = inject(QSharedResizeObserverService);
  private readonly _elementRef = inject(ElementRef);
  private readonly _renderer = inject(Renderer2);

  ngOnInit(): void {
    this._initializeResizeObserver();
    if (!this._activeItem) {
      this._activeItem = 1;
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { type, size } = changes;

    if (type?.currentValue || size?.currentValue) {
      this._resetActiveItem();
    }
  }

  ngAfterViewInit(): void {
    this._resetActiveItem();
  }

  _numSequence(n: number): number[] {
    return Array<number>(n);
  }

  _onClick(active: number): void {
    this._updateActiveIndicator(active);
  }

  get gapSize(): number {
    return this.type === 'tight'
      ? parseInt(this._getComputedStyle().getPropertyValue('--ads-size-micro'))
      : parseInt(this._getComputedStyle().getPropertyValue('--ads-size-xxxs'));
  }

  get growSize(): number {
    return this._activeOffset > 0
      ? this.itemSize + this._activeOffset * (this.itemSize + this.gapSize)
      : this._activeOffset < 0
        ? this.itemSize + Math.abs(this._activeOffset * (this.itemSize + this.gapSize))
        : this.itemSize;
  }

  get itemSize(): number {
    const sizeMap: { [key in QCarouselSize]: string } = {
      small: '--ads-size-nano',
      medium: '--ads-size-micro',
      large: '--ads-size-xxxs',
    };

    return parseInt(this._getComputedStyle().getPropertyValue(sizeMap[this.size]));
  }

  private _getComputedStyle(): CSSStyleDeclaration {
    return getComputedStyle(this._elementRef.nativeElement);
  }

  private _initializeResizeObserver(): void {
    this._resizeObserver
      .observe(this._elementRef.nativeElement)
      ?.pipe(takeUntil(this._destroy$))
      .subscribe(() => this._resetActiveItem());
  }

  private _getGapSize(): number {
    return this.type === 'tight'
      ? parseInt(this._getComputedStyle().getPropertyValue('--ads-size-micro'))
      : parseInt(this._getComputedStyle().getPropertyValue('--ads-size-xxxs'));
  }

  private _getItemSize(): number {
    const sizeMap: { [key in QCarouselSize]: string } = {
      small: '--ads-size-nano',
      medium: '--ads-size-micro',
      large: '--ads-size-xxxs',
    };

    return parseInt(this._getComputedStyle().getPropertyValue(sizeMap[this.size]));
  }

  private _resetActiveItem(): void {
    if (this.activeItemRef) {
      this._activeItemIndicatorXPosition =
        (this._activeItem - 1) * (this._getItemSize() + this._getGapSize());

      this._renderer.setStyle(
        this.activeItemRef.nativeElement,
        'transform',
        `translate(${this._activeItemIndicatorXPosition}px)`,
      );
    }
  }

  private _updateActiveIndicator(active: number): void {
    this._oldActiveItem = this._activeItem;
    this._activeItem = active > MAX_INDICATORS ? MAX_INDICATORS : active;
    this.changed.emit(active);
    this._animate();
  }

  private _animate(): void {
    this._activeOffset = this._activeItem - this._oldActiveItem;
    this._activeItemIndicatorXPosition += this._activeOffset * (this.itemSize + this.gapSize);

    if (this._activeOffset > 0) {
      this._animateRight = true;
    } else {
      this._animateLeft = true;
    }
  }
}
